use vstd::prelude::*;

verus! {

    // Specification for the swap_first_and_last function
    fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
        requires
            a.len() > 0, // The input array must be non-empty
        ensures
            result.len() == a.len() // The result array has the same length as the input
            && (if a.len() == 1 {
                result[0] == a[0] // If the length is 1, the result is identical to the input
            } else {
                result[0] == a[a.len() - 1] // The first element of the result is the last element of the input
                && result[result.len() - 1] == a[0] // The last element of the result is the first element of the input
                && forall(|i: nat| 1 <= i && i < (a.len() - 1) as nat ==> result[i as usize] == a[i as usize]) // Interior elements remain unchanged
            })
    {
        let n = a.len();
        let mut result = Vec::with_capacity(n); // Create a new vector with the same capacity

        if n == 1 {
            result.push(a[0]); // If the length is 1, copy the single element
        } else {
            result.push(a[n - 1]); // Swap the first element
            for i in 1..(n - 1) {
                result.push(a[i]); // Copy the interior elements
            }
            result.push(a[0]); // Swap the last element
        }

        result // Return the result vector
    }
}

